//
// write_byte dispatches through a function pointer.
// Default: HOSTED/MCU32 → putchar wrapper.  Other MCU → NULL (call console::init(fn) before use).
// Override at runtime: console::init(fn) for custom transports (UART, USB, mock tests).

#if HOSTED || MCU32
@raw("#include <stdio.h>")

@extern("putchar({b})")
fun _putchar(b: u8)

fun _write_byte_default(b: u8)
    _putchar(b)

var _write_byte: fun(u8) = _write_byte_default
#else
var _write_byte: fun(u8)
#end

fun init(write_byte: fun(u8))
    _write_byte = write_byte

@inline
fun write_byte(b: u8)
    _write_byte(b)

// ── primitives ───────────────────────────────────────────────────────────────

fun println()
    write_byte(10)

fun print_str(s: u8[])
    var i: u32 = 0
    while i < s.size()
        write_byte(s[i])
        i += 1

fun print_bool(v: bool)
    if v
        write_byte('t')
        write_byte('r')
        write_byte('u')
        write_byte('e')
    else
        write_byte('f')
        write_byte('a')
        write_byte('l')
        write_byte('s')
        write_byte('e')

// ── unsigned integers ─────────────────────────────────────────────────────────

fun print_u64(v: u64)
    var buf: u8[20]
    var i: i32 = 19
    if v == 0
        write_byte('0')
        return
    while v > 0
        buf[i] = u8(v % 10 + 48)
        v = v / 10
        i -= 1
    var j: i32 = i + 1
    while j < 20
        write_byte(buf[j])
        j += 1

fun print_u32(v: u32)
    print_u64(u64(v))

fun print_u16(v: u16)
    print_u64(u64(v))

fun print_u8(v: u8)
