        _fwrite(s, _handle)

    fun read_line(buf: u8[]): u32
        if _fgets(buf, _handle) == false
            return 0
        var i: u32 = 0
        while i < buf.size()
            if buf[i] == 0
                return i
            i += 1
        return buf.size()

