import mcu32.memory::Allocator

// ── ArrayList ─────────────────────────────────────────────────────────────────
// Fixed-capacity list backed by an Allocator. Works on MCU and hosted.
// push/insert return false when full.

class ArrayList<T>()
    var _buffer: T[]
    var _size: u32 = 0

    fun init(alloc: &Allocator, capacity: u32) bool
        _buffer = alloc.allocate_array<T>(capacity)
        if _buffer.size() == 0
            return false
        return true

    @inline
    fun push(value: T) bool
        if _size >= _buffer.size()
            return false
        _buffer[_size] = value
        _size += 1
        return true

    @inline
    fun pop() bool
        if _size == 0
            return false
        _size -= 1
        return true

    fun insert(i: u32, value: T) bool
        if _size >= _buffer.size()
            return false
        if i > _size
            return false
        var j: u32 = _size
        while j > i
            _buffer[j] = _buffer[j - 1]
            j -= 1
        _buffer[i] = value
        _size += 1
        return true

    @inline
    fun get(i: u32) T
        return _buffer[i]

    @inline
    fun set(i: u32, value: T)
        _buffer[i] = value

    @inline
    fun top() T
        return _buffer[_size - 1]

    @inline
    fun size() u32
        return _size

    @inline
    fun capacity() u32
        return _buffer.size()

    @inline
    fun is_empty() bool
        return _size == 0

    @inline
    fun is_full() bool
        return _size >= _buffer.size()

    @inline
    fun clear()
        _size = 0

// ── RingBuffer ────────────────────────────────────────────────────────────────
// Fixed-capacity circular buffer backed by an Allocator.

class RingBuffer<T>()
    var _buffer: T[]
    var _head: u32 = 0
    var _tail: u32 = 0
    var _size: u32 = 0

    fun init(allocator: &Allocator, capacity: u32) bool
        _buffer = allocator.allocate_array<T>(capacity)
        if _buffer.size() == 0
            return false
        return true

    @inline
    fun push(value: T) bool
        if _size >= _buffer.size()
            return false
        _buffer[_tail] = value
        _tail = (_tail + 1) % _buffer.size()
        _size += 1
        return true

    @inline
    fun pop() bool
        if _size == 0
            return false
        _head = (_head + 1) % _buffer.size()
        _size -= 1
        return true

    @inline
    fun peek() T
        return _buffer[_head]

    @inline
    fun size() u32
        return _size

    @inline
    fun capacity() u32
        return _buffer.size()

    @inline
    fun is_empty() bool
        return _size == 0

    @inline
    fun is_full() bool
        return _size >= _buffer.size()
        
#end
""",
  'mcu32.memory': """#if HOSTED || MCU32

class Allocator()
    var _memory: u8[] = {null, 0}
    var _cursor: u32 = 0

    fun init(mem: u8[])
        _memory = mem
        _cursor = 0

    @inline
    fun allocate<T>(): &T
        val size := sizeof<T>()
        if _cursor + size > _memory.size()
            return null
        val ptr := &T(&_memory[_cursor])
        _cursor = (_cursor + size + 3) & ~u32(3)
        return ptr

    @inline
    fun allocate_array<T>(length: u32): T[]
        val size := sizeof<T>() * length
        if _cursor + size > _memory.size()
            return {null, 0}
        val ptr := &T(&_memory[_cursor])
        _cursor = (_cursor + size + 3) & ~u32(3)
        return {ptr, length}

    @inline
    fun reset()
        _cursor = 0

#end
""",
  'string': """// ── Comparison / search ───────────────────────────────────────────────────────

fun equals(a: u8[], b: u8[]): bool
    if a.size() != b.size()
        return false
    var i: u32 = 0
    while i < a.size()
        if a[i] != b[i]
            return false
        i += 1
    return true

fun starts_with(s: u8[], prefix: u8[]): bool
    if prefix.size() > s.size()
        return false
    var i: u32 = 0
    while i < prefix.size()
        if s[i] != prefix[i]
            return false
        i += 1
    return true

fun ends_with(s: u8[], suffix: u8[]): bool
    if suffix.size() > s.size()
        return false
    val offset := s.size() - suffix.size()
    var i: u32 = 0
    while i < suffix.size()
        if s[offset + i] != suffix[i]
            return false
        i += 1
    return true

fun index_of(s: u8[], c: u8): i32
    var i: u32 = 0
    while i < s.size()
        if s[i] == c
            return i32(i)
        i += 1
    return -1

// ── Slicing ───────────────────────────────────────────────────────────────────

fun sub(s: u8[], start: u32, len: u32): u8[]
    return {s.ptr + start, len}

fun trim_start(s: u8[]): u8[]
    var i: u32 = 0
    while i < s.size()
        val c := s[i]
        if c != 32 && c != 9 && c != 10 && c != 13
            return {s.ptr + i, s.size() - i}
        i += 1
    return {s.ptr, 0}

fun trim_end(s: u8[]): u8[]
    if s.size() == 0
        return s
    var i := s.size() - 1
    while i > 0
        val c := s[i]
        if c != 32 && c != 9 && c != 10 && c != 13
            return {s.ptr, i + 1}
        i -= 1
    val c := s[0]
    if c != 32 && c != 9 && c != 10 && c != 13
        return {s.ptr, 1}
    return {s.ptr, 0}

fun trim(s: u8[]): u8[]
    return trim_end(trim_start(s))

// ── Tokenization ──────────────────────────────────────────────────────────────

// Returns the token starting at `start` up to (not including) the next `delim`
// or end of string.
fun token(s: u8[], start: u32, delim: u8): u8[]
    var i := start
    while i < s.size()
        if s[i] == delim
            return {s.ptr + start, i - start}
        i += 1
    return {s.ptr + start, s.size() - start}

// Advances past any `delim` bytes starting at `start`. Use after token() to
// move to the next field.
fun skip(s: u8[], start: u32, delim: u8): u32
    var i := start
    while i < s.size()
        if s[i] != delim
            return i
        i += 1
    return s.size()

// ── Number parsing ────────────────────────────────────────────────────────────

fun parse_u32(s: u8[]): u32
    var result: u32 = 0
    var i: u32 = 0
    while i < s.size()
        val c := s[i]
        if c < 48 || c > 57
            return result
        result = result * 10 + u32(c - 48)
        i += 1
    return result

fun parse_i32(s: u8[]): i32
    if s.size() == 0
        return 0
    if s[0] == 45
        val abs := parse_u32({s.ptr + 1, s.size() - 1})
        return i32(-abs)
    return i32(parse_u32(s))

// ── Number formatting ─────────────────────────────────────────────────────────

// Writes decimal representation of `v` into `buf`. Returns number of bytes
// written. buf must be at least 10 bytes.
fun format_u32(buf: u8[], v: u32): u32
    if v == 0
        buf[0] = 48
        return 1
    var tmp: u8[10]
    var len: u32 = 0
    var n := v
    while n > 0
        tmp[len] = u8(48 + n % 10)
        n = n / 10
        len += 1
    var i: u32 = 0
    while i < len
        buf[i] = tmp[len - 1 - i]
        i += 1
    return len

// Writes decimal representation of `v` into `buf`. Returns bytes written.
// buf must be at least 11 bytes.
fun format_i32(buf: u8[], v: i32): u32
    if v < 0
        buf[0] = 45
        val written := format_u32({buf.ptr + 1, buf.size() - 1}, u32(-v))
        return written + 1
    return format_u32(buf, u32(v))

// ── String building ───────────────────────────────────────────────────────────
//
// Renders `text` into `buf`, replacing {Ni} {Nu} {Nf} {Nd} {Nb} placeholders.
// All args are stored as i32 — the type specifier controls formatting:
//   {0i}  signed int (default when no specifier)
//   {0u}  unsigned int
//   {0f}  float       — pass bits via float_bits(v)
//   {0d}  fixed 16.16 — pass as i32(v) (fixed is i32 internally)
//   {0b}  bool        — prints "true" / "false"
//
// Returns a u8[] slice into buf with the final length.
//
// Example:
//   var buf:  u8[64]
//   var args: i32[3] = {hp, max_hp, i32(alive)}
//   val s := build_string("HP: {0i}/{1i} alive={2b}", buf, args)

// Bit-cast helpers — raw 32-bit reinterpret, no value conversion.
@raw("static inline int32_t __mp_float_to_bits(float f) { int32_t v; __builtin_memcpy(&v, &f, 4); return v; }")
@raw("static inline float __mp_bits_to_float(int32_t v) { float f; __builtin_memcpy(&f, &v, 4); return f; }")

@extern("__mp_float_to_bits")
fun float_bits(f: float) i32

@extern("__mp_bits_to_float")
fun _bits_to_float(v: i32) float

// fixed and i32 share the same 32-bit representation — this is the explicit,
// intention-clear way to pass a fixed value into an i32[] args array.
// Do NOT use i32(my_fixed): semantically that means "extract integer part".
@extern("((int32_t){f})")
fun fixed_bits(f: fixed) i32

fun _format_float(buf: u8[], v: float) u32
    var bi: u32 = 0
    var abs: float = v
    if v < 0.0
        buf[bi] = 45  // '-'
        bi += 1
        abs = 0.0 - v
    val int_part := i32(abs)
    bi += format_i32({buf.ptr + bi, buf.size() - bi}, int_part)
    buf[bi] = 46  // '.'
    bi += 1
    var frac: float = abs - float(int_part)
    var d: u32 = 0
    while d < 2
        frac = frac * 10.0
        val digit := i32(frac)
        buf[bi] = u8(digit + 48)
        bi += 1
        frac = frac - float(digit)
        d += 1
    return bi

fun _format_fixed(buf: u8[], v: i32) u32
    var bi: u32 = 0
    var abs: u32 = 0
    if v < 0
        buf[bi] = 45  // '-'
        bi += 1
        abs = u32(0 - v)
    else
        abs = u32(v)
    bi += format_u32({buf.ptr + bi, buf.size() - bi}, abs >> 16)
    buf[bi] = 46  // '.'
    bi += 1
    var frac: u32 = abs & 0xFFFF
    var d: u32 = 0
    while d < 2
        frac *= 10
        buf[bi] = u8((frac >> 16) + 48)
        bi += 1
        frac = frac & 0xFFFF
        d += 1
    return bi

fun _format_bool(buf: u8[], v: i32) u32
    if v != 0
        buf[0] = 't'
        buf[1] = 'r'
        buf[2] = 'u'
        buf[3] = 'e'
        return 4
    buf[0] = 'f'
    buf[1] = 'a'
    buf[2] = 'l'
    buf[3] = 's'
    buf[4] = 'e'
    return 5

fun build_string(text: u8[], buf: u8[], args: i32[]): u8[]
    var ti: u32 = 0
    var bi: u32 = 0
    while ti < text.size() && bi < buf.size()
        val c := text[ti]
        if c == '{'
            ti += 1
            var idx: i32 = 0
            while ti < text.size() && text[ti] != '}' && text[ti] != 'i' && text[ti] != 'u' && text[ti] != 'f' && text[ti] != 'd' && text[ti] != 'b'
                idx = idx * 10 + i32(text[ti]) - 48
                ti += 1
            var spec: u8 = 'i'
            if ti < text.size() && text[ti] != '}'
                spec = text[ti]
                ti += 1
            ti += 1  // skip '}'
            if idx >= 0 && idx < i32(args.size())
                val sub := {buf.ptr + bi, buf.size() - bi}
                var written: u32 = 0
                if spec == 'u'
                    written = format_u32(sub, u32(args[idx]))
                else if spec == 'f'
                    written = _format_float(sub, _bits_to_float(args[idx]))
                else if spec == 'd'
                    written = _format_fixed(sub, args[idx])
                else if spec == 'b'
                    written = _format_bool(sub, args[idx])
                else
                    written = format_i32(sub, args[idx])
                bi += written
        else
            buf[bi] = c
            bi += 1
            ti += 1
    return {buf.ptr, bi}
""",
  'test': """import console::*

// ── global counters (test-level, not assert-level) ────────────────────────────

var _succeeded: u32 = 0
var _failed: u32 = 0

// ── per-test state ────────────────────────────────────────────────────────────

var _current_name: u8[] = ""
var _current_failed: u32 = 0

// failure buffer: up to 8 failures per test
var _buf_count: u32 = 0
var _buf_lines: u32[8]
var _buf_files: u8[][8]
var _buf_exprs: u8[][8]

// ── called by generated assert code ──────────────────────────────────────────

fun _test_pass()
    // counted at test level in _test_end, nothing to do per assert

fun _test_fail(file: u8[], line: u32, expr: u8[])
    if _buf_count < 8
        _buf_files[_buf_count] = file
        _buf_lines[_buf_count] = line
        _buf_exprs[_buf_count] = expr
        _buf_count += 1
    _current_failed += 1

// ── called by generated test main() ──────────────────────────────────────────

fun _test_begin(name: u8[])
    _current_name = name
    _current_failed = 0
    _buf_count = 0

fun _test_end()
    if _current_failed == 0
        print_str("\\x1b[32mP:")
        print_str(_current_name)
        print_str("\\x1b[0m")
        println()
        _succeeded += 1
    else
        print_str("\\x1b[31mF:")
        print_str(_current_name)
        print_str("\\x1b[0m")
        println()
        var i: u32 = 0
        while i < _buf_count
            print_str("  ")
            print_str(_buf_files[i])
            print_str(":")
            print_u32(_buf_lines[i])
            print_str(": ")
            print_str(_buf_exprs[i])
            println()
            i += 1
        _failed += 1

fun _report() i32
    print_str("DONE ")
    print_u32(_succeeded)
    print_str("/")
    print_u32(_succeeded + _failed)
    println()
    if _failed > 0
        return 1
    return 0
""",
};
